<?php require_once __DIR__.'/_common.php';$riwayat=get_riwayat($pdo,$idLansia);$latest=[];foreach($riwayat as $r)if(!isset($latest[$r['id_lansia']]))$latest[$r['id_lansia']]=$r;awal_halaman('Deteksi Risiko & Saran','risiko'); ?>
<section class="f-intro"><h1>Deteksi Risiko & Saran</h1><p>Status kondisi ditampilkan berdasarkan hasil pemeriksaan terakhir yang tercatat di sistem. Saran mengikuti catatan kader dan bukan diagnosis medis.</p></section><div class="f-note">Jika hasil pemeriksaan mencatat rujukan Puskesmas atau risiko tinggi, segera hubungi kader atau Puskesmas dan ikuti arahan tenaga kesehatan.</div>
<?php if($daftarLansia):foreach($daftarLansia as $l):$r=$latest[$l['id_lansia']]??null;?><section class="f-card"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><h3 style="margin:0"><?=h($l['nama_lengkap'])?></h3><?php if($r):?><span class="f-badge <?=warna_status($r['status_kondisi'])?>"><?=h($r['status_kondisi'])?></span><?php else:?><span class="f-badge muted">Belum diperiksa</span><?php endif;?></div>
<?php if($r):?><p style="font-size:10px;color:#82909c">Pemeriksaan terakhir: <?=tgl_id($r['tanggal_pemeriksaan'])?> pukul <?=jam_id($r['waktu_pemeriksaan'])?></p><div class="f-detail">
<div class="f-field"><small>Tekanan darah</small><strong><?=(int)$r['tensi_sistolik']?>/<?=(int)$r['tensi_diastolik']?> mmHg · <?=h($r['status_tensi'])?></strong></div><div class="f-field"><small>IMT</small><strong><?=h($r['imt'])?> · <?=h($r['status_imt'])?></strong></div><div class="f-field"><small>Gula darah</small><strong><?=$r['gula_darah']===null?'Tidak diperiksa':h($r['gula_darah']).' mg/dL · '.h($r['status_gula_darah'])?></strong></div><div class="f-field"><small>Kolesterol</small><strong><?=$r['kolesterol']===null?'Tidak diperiksa':h($r['kolesterol']).' mg/dL · '.h($r['status_kolesterol'])?></strong></div><div class="f-field"><small>Asam urat</small><strong><?=$r['asam_urat']===null?'Tidak diperiksa':h($r['asam_urat']).' mg/dL · '.h($r['status_asam_urat'])?></strong></div><div class="f-field"><small>Detak jantung / suhu</small><strong><?=(int)$r['detak_jantung']?> bpm / <?=h($r['suhu_tubuh'])?> °C</strong></div></div>
<div style="margin-top:14px;padding:13px;background:#f8fafb;border-radius:10px;font-size:11px;line-height:1.7;color:#526272"><b>Saran / catatan kader:</b><br><?=nl2br(h($r['catatan_kader']?:'Belum ada saran khusus dari kader.'))?><br><b>Keluhan:</b> <?=h($r['keluhan']?:'Tidak ada keluhan yang dicatat')?><br><b>Rujukan Puskesmas:</b> <span class="f-badge <?=warna_status($r['rujukan_puskesmas'])?>"><?=h($r['rujukan_puskesmas'])?></span></div>
<?php if($r['rujukan_puskesmas']==='Ya'||$r['status_kondisi']==='Risiko Tinggi'):?><div class="f-note" style="margin:14px 0 0">Catatan pemeriksaan menunjukkan rujukan atau status risiko tinggi. Hubungi kader atau Puskesmas untuk arahan lanjutan.</div><?php elseif($r['status_kondisi']==='Perlu Perhatian'):?><div class="f-note" style="margin:14px 0 0">Perlu perhatian: ikuti saran kader dan lakukan pemeriksaan ulang sesuai jadwal Posyandu atau arahan tenaga kesehatan.</div><?php else:?><div style="margin-top:14px;padding:12px;background:#eaf7ef;border-radius:10px;color:#24734b;font-size:11px">Status terakhir tercatat aman/sehat. Tetap ikuti pemeriksaan rutin.</div><?php endif;?>
<?php else:?><div class="f-empty">Belum ada hasil pemeriksaan. Status risiko belum dapat ditampilkan.</div><?php endif;?></section><?php endforeach;else:?><section class="f-card"><div class="f-empty">Belum ada data lansia yang terhubung dengan akun keluarga ini.</div></section><?php endif;?><?php akhir_halaman(); ?>
